  ok: true,
  period_start: $('Rank Top Issues').first().json.period_start,
  period_end: $('Rank Top Issues').first().json.period_end,
  batch_id: $('Rank Top Issues').first().json.triggerParams.batch_id,
  total_feedback: $('Rank Top Issues').first().json.total_feedback,
  top_issues: $('Rank Top Issues').first().json.top_issues
}) }}
